{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C16"],
      "claim": "Brepocitinib, a structurally related oral kinase inhibitor with a heteroaromatic amine and amide, had absolute oral bioavailability of 75% in a human mass-balance study, directly supporting F ≥ 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C10"],
      "claim": "Basmisanil, the highest-transfer analogue, showed approximately 75% absolute oral bioavailability in humans after a 45 mg tablet dose, supporting high oral bioavailability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C17"],
      "claim": "Suvorexant, a human drug with a difluorophenyl/amide heteroaromatic scaffold, had mean oral bioavailability of 82%, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C12"],
      "claim": "Alpelisib, which shares a urea/pyrrolidine and heteroaromatic motif with the query, had approximately 68.7% oral bioavailability in healthy subjects, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C23"],
      "claim": "Navoximod, a fluorinated heteroaromatic drug, had 55.5% absolute oral bioavailability in healthy subjects after a 200 mg oral dose, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C05"],
      "claim": "Vernakalant, containing a hydroxypyrrolidine similar to the query's hydroxyazetidine, had absolute oral bioavailability of 71 ± 21% in healthy volunteers, supporting high F.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "All high-transfer human evidence records report oral bioavailability values between 46% and 100%, uniformly above the 20% threshold; the query's drug-like heteroaromatic scaffold and close structural parallels to oral kinase inhibitors make high absolute oral bioavailability the best-supported prediction.",
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement exists for the query molecule itself.",
    "No close analogue with low oral bioavailability was retrieved, so the negative space is not directly constrained.",
    "Specific query properties such as aqueous solubility, permeability, and first-pass metabolism are not experimentally characterized."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

